/* Manim video player for { t: 'video', id: 'eigen' } blocks.
 * Videos and their step start times come from data/videos.js (generated by manim/render.py).
 * Under the video every step's full caption is listed (Markdown + KaTeX); clicking a step jumps there.
 * ⏭ plays exactly one step and pauses; ▶ plays to the end. 🔊 toggles the soft sound cues (remembered site-wide). */
(function (root) {
  'use strict';
  const SML = root.SML;
  const { md, inline, esc } = SML.md;
  const EPS = 0.06;      // pause this far before the next step starts, so its first frame is not shown
  const MUTE_KEY = 'sml-video-muted';   // sound preference shared by every video on the site

  function loadMuted() { try { return localStorage.getItem(MUTE_KEY) === '1'; } catch (e) { return false; } }
  function saveMuted(m) { try { localStorage.setItem(MUTE_KEY, m ? '1' : '0'); } catch (e) { /* storage blocked */ } }

  function el(tag, cls, html) {
    const n = document.createElement(tag);
    if (cls) n.className = cls;
    if (html != null) n.innerHTML = html;
    return n;
  }
  function fmt(t) {
    t = Math.max(0, Math.floor(t || 0));
    return Math.floor(t / 60) + ':' + String(t % 60).padStart(2, '0');
  }

  function mount(b) {
    const v = SML.videos && SML.videos[b.id];
    if (!v) return el('div', 'pending-box', '视频 <code>' + esc(b.id) + '</code> 还没有渲染');
    const steps = v.steps || [];
    const box = el('div', 'anim-box video-box');
    const head = el('div', 'anim-head');
    head.appendChild(el('span', 'anim-title', inline(b.title || v.title || '')));
    head.appendChild(el('span', 'anim-badge', '视频'));

    const stage = el('div', 'video-stage');
    const video = el('video');
    video.src = v.src; video.poster = v.poster; video.preload = 'metadata';
    video.playsInline = true; video.muted = loadMuted(); video.volume = 0.8; video.setAttribute('playsinline', '');
    const big = el('button', 'video-big', '▶'); big.type = 'button'; big.title = '播放';
    stage.append(video, big);

    const track = el('div', 'video-track');
    const fill = el('div', 'video-fill');
    track.appendChild(fill);
    steps.forEach((s, i) => {
      const m = el('i', 'video-tick'); m.style.left = (100 * s.t / v.dur) + '%'; m.title = '第 ' + (i + 1) + ' 步';
      track.appendChild(m);
    });

    const bar = el('div', 'anim-bar');
    const btn = (txt, title, cls) => { const x = el('button', 'btn' + (cls ? ' ' + cls : ''), txt); x.type = 'button'; x.title = title; return x; };
    const bPrev = btn('⏮', '上一步'), bPlay = btn('▶ 播放', '连续播放到结尾', 'primary'), bNext = btn('⏭ 下一步', '只播下一步，播完自动暂停'), bRe = btn('↺', '从头开始');
    const speed = el('select', 'anim-speed');
    [['0.75', '慢'], ['1', '1×'], ['1.25', '1.25×'], ['1.5', '快']].forEach(([x, t]) => { const o = el('option', null, t); o.value = x; speed.appendChild(o); });
    speed.value = '1';
    const bSound = btn('', '音效开关', 'video-sound');
    const showSound = () => { bSound.textContent = video.muted ? '🔇' : '🔊'; bSound.title = video.muted ? '打开音效' : '关闭音效'; };
    showSound();
    const clock = el('span', 'video-clock');
    bar.append(bPrev, bPlay, bNext, bRe, speed, bSound, clock);

    const list = el('ol', 'video-steps');
    const items = steps.map((s, i) => {
      const li = el('li', null, '<span class="video-step-time">' + fmt(s.t) + '</span>');
      const body = el('div', 'video-step-say', md(s.say));
      li.appendChild(body);
      li.title = '跳到第 ' + (i + 1) + ' 步';
      li.addEventListener('click', (e) => { if (e.target.closest('a')) return; playStep(i); });
      list.appendChild(li);
      return li;
    });
    const hint = el('div', 'video-hint', '点 **▶** 连续看完；点 **⏭ 下一步** 每次只播一步、播完自动停；点下面任意一步直接跳过去。'.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>'));

    box.append(head, stage, track, bar, hint, list);

    let stopAt = null, raf = 0;
    const startOf = (k) => (k <= 0 ? 0 : steps[k].t);
    const endOf = (k) => (k + 1 < steps.length ? steps[k + 1].t - EPS : v.dur);
    function current() {           // index of the step being shown (−1 before the first step starts)
      const t = video.currentTime + 0.02;
      let k = -1;
      steps.forEach((s, i) => { if (t >= s.t) k = i; });
      return k;
    }
    function paint() {
      const k = current(), dur = video.duration || v.dur;
      items.forEach((li, i) => li.classList.toggle('on', i === k));
      fill.style.width = (100 * video.currentTime / dur) + '%';
      clock.textContent = fmt(video.currentTime) + ' / ' + fmt(dur) + (k >= 0 ? '　第 ' + (k + 1) + ' / ' + steps.length + ' 步' : '');
      const playing = !video.paused && !video.ended;
      bPlay.textContent = playing && stopAt == null ? '⏸ 暂停' : video.ended || video.currentTime >= dur - 0.05 ? '▶ 重播' : '▶ 播放';
      big.hidden = playing;
      bPrev.disabled = video.currentTime < 0.3;
      bNext.disabled = k >= steps.length - 1 && !playing;
    }
    function watch() {             // rAF is precise enough to stop on a step boundary (timeupdate fires ~4×/s)
      cancelAnimationFrame(raf);
      const loop = () => {
        if (stopAt != null && video.currentTime >= stopAt) {
          video.pause(); video.currentTime = stopAt; stopAt = null;
        }
        paint();
        if (!video.paused) raf = requestAnimationFrame(loop);
      };
      raf = requestAnimationFrame(loop);
    }
    function go(t, until) {
      stopAt = until == null ? null : until;
      video.currentTime = Math.max(0, t);
      const p = video.play();
      if (p && p.catch) p.catch(() => {});
      watch();
    }
    function playStep(k) { go(startOf(k), endOf(k)); }
    function next() {
      if (!video.paused && stopAt != null) { video.currentTime = stopAt; video.pause(); stopAt = null; paint(); return; }  // a running step jumps to its end
      const k = current();
      if (k < steps.length - 1) playStep(k + 1);
    }
    function prev() {             // well into a step → replay it; near its start → the step before
      const k = current();
      const into = k >= 0 ? video.currentTime - steps[k].t : 0;
      playStep(into > 1.2 ? Math.max(0, k) : Math.max(0, k - 1));
    }
    function toggle() {
      if (!video.paused && stopAt == null) { video.pause(); paint(); return; }
      if (video.ended || video.currentTime >= (video.duration || v.dur) - 0.05) go(0, null);
      else go(video.currentTime, null);
    }

    bPlay.addEventListener('click', toggle);
    big.addEventListener('click', toggle);
    video.addEventListener('click', toggle);
    bNext.addEventListener('click', next);
    bPrev.addEventListener('click', prev);
    bRe.addEventListener('click', () => { video.pause(); stopAt = null; video.currentTime = 0; paint(); });
    speed.addEventListener('change', () => { video.playbackRate = parseFloat(speed.value) || 1; });
    bSound.addEventListener('click', () => { video.muted = !video.muted; saveMuted(video.muted); showSound(); });
    track.addEventListener('click', (e) => {
      const r = track.getBoundingClientRect();
      const t = (e.clientX - r.left) / r.width * (video.duration || v.dur);
      stopAt = null; video.currentTime = t; paint();
    });
    ['pause', 'play', 'seeked', 'loadedmetadata', 'ended', 'timeupdate'].forEach((ev) => video.addEventListener(ev, paint));
    paint();
    return box;
  }

  SML.video = { mount: mount };
})(window);
